function extractCreatorFromStream(sf) {
  const fs = require('fs');
  const path = require('path');
  let handle = '';
  try {
    if (sf) {
      const stem = sf.replace(/(\.processing)?\.mp4$/i, '');
      const candidates = [
        path.join('/files/inputs', stem + '.processing.info.json'),
        path.join('/files/inputs', stem + '.info.json'),
        path.join('/files/inputs', sf + '.info.json'),
      ];
      for (const ip of candidates) {
        if (fs.existsSync(ip)) {
          const info = JSON.parse(fs.readFileSync(ip, 'utf8'));
          let rawUid = String(info.uploader_id || '').trim().replace(/^@/, '');
          const rawUp = String(info.uploader || info.channel || '').trim().replace(/^@/, '');
          if (/^UC[A-Za-z0-9_-]{22}$/.test(rawUid) && rawUp) rawUid = rawUp;
          const raw = rawUid || rawUp;
          if (raw) { handle = raw.replace(/\s+/g, ''); break; }
        }
      }
      if (!handle) {
        const atM = sf.match(/@([A-Za-z0-9_]+)/);
        const chunkM = sf.match(/^([A-Za-z0-9_-]+?)_(?:vod_\d+|[A-Za-z0-9_-]{11})_chunk\d+/i)
          || sf.match(/^([A-Za-z0-9-]+_?)_[A-Za-z0-9_-]+_chunk\d+/i)
          || sf.match(/^([A-Za-z0-9_-]+)_[A-Za-z0-9_-]+_chunk\d+/i);
        if (atM) handle = atM[1];
        else if (chunkM) handle = chunkM[1];
        else {
          const prefM = sf.match(/^(?:\d+_Top_)?([A-Za-z0-9_]+)___/i);
          if (prefM) handle = prefM[1];
        }
      }
    }
  } catch (e) {}
  return handle;
}
const fs = require('fs');
try {
  const sd = $getWorkflowStaticData('global');
  sd._scout_primary_dead = false;
  sd._scout_consec_429 = 0;
  sd._summary_retry_count = 0;
  sd._director_retry_count = 0;
